package com.saga.be.service.ai;
import com.fasterxml.jackson.databind.ObjectMapper; import com.saga.be.entity.enums.AiEvidenceType; import java.util.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Component;
@Component @Profile("!test") public class AiAcademicCandidateEvidenceBuilder {
 private final ObjectMapper mapper; public AiAcademicCandidateEvidenceBuilder(ObjectMapper mapper){this.mapper=mapper;}
 public List<AiEvidenceDraft> build(AiAcademicContextService.Context c){List<AiEvidenceDraft> out=new ArrayList<>();out.add(row(AiEvidenceType.SYLLABUS_VERSION,"syllabus:"+c.syllabusVersion().getId(),Map.of("syllabusVersionId",c.syllabusVersion().getId(),"versionLabel",c.syllabusVersion().getVersionLabel()),Map.of("candidateContext","COMPLETE","syllabusVersionId",c.syllabusVersion().getId()))); for(var p:c.phases())out.add(row(AiEvidenceType.SYLLABUS_PHASE,"phase:"+p.getId(),Map.of("targetType","PHASE","targetId",p.getId(),"syllabusVersionId",c.syllabusVersion().getId(),"code",p.getCode(),"name",p.getName(),"description",p.getDescription()==null?"":p.getDescription(),"orderIndex",p.getOrderIndex()))); for(var d:c.deliverables())out.add(row(AiEvidenceType.SYLLABUS_DELIVERABLE,"deliverable:"+d.getId(),Map.of("targetType","EXPECTED_DELIVERABLE","targetId",d.getId(),"syllabusVersionId",c.syllabusVersion().getId(),"code",d.getCode(),"name",d.getName(),"description",d.getDescription()==null?"":d.getDescription(),"orderIndex",d.getOrderIndex(),"phaseId",d.getPhaseId())));return List.copyOf(out);}
 private AiEvidenceDraft row(AiEvidenceType t,String ref,Object p){return row(t,ref,p,null);} private AiEvidenceDraft row(AiEvidenceType t,String ref,Object p,Object metadata){try{return new AiEvidenceDraft(t,ref,mapper.writeValueAsString(p),metadata==null?null:mapper.writeValueAsString(metadata));}catch(Exception e){throw new IllegalStateException(e);}}
}
